Bytes ScriptSession::encodeTrackables(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=16u*1024u*1024u;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Trackable snapshot requires a quiescent local session");std::vector<std::pair<std::uint32_t,std::uint32_t>> handles;std::set<std::uint32_t> stable;size_t liveCount=0;for(size_t i=0;i<objects_.size();++i)if(objects_[i].kind==NativeKind::Trackable){auto id=handleBase+std::uint32_t(i),saved=encodeHandle?encodeHandle("trackable",id):0;if(!saved || !stable.insert(saved).second)throw std::runtime_error("Invalid trackable identity mapping");handles.emplace_back(saved,id);if(objects_[i].alive)++liveCount;}if(handles.size()>65536 || liveCount>8192 || liveCount!=trackables_.size())throw std::runtime_error("Trackable identity budget or state differs");std::sort(handles.begin(),handles.end());SnapshotWriter out(budget-64);out.u32(tag("STKB"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.size(handles.size());for(auto [saved,id]:handles){auto& object=objects_[id-handleBase];out.u32(saved);out.u32(object.alive?1:0);if(!object.alive)continue;auto state=std::get<std::shared_ptr<ScriptTrackable>>(object.state);if(!state || !trackables_.contains(id) || trackables_.at(id)!=state || state->model.empty() || !std::isfinite(state->x) || !std::isfinite(state->y) || !std::isfinite(state->facing))throw std::runtime_error("Invalid trackable state");out.text(state->model,65536);out.u32(std::bit_cast<std::uint32_t>(state->x));out.u32(std::bit_cast<std::uint32_t>(state->y));out.u32(std::bit_cast<std::uint32_t>(state->facing));}return sealSnapshot(out.finish(),budget);
}
std::map<std::uint32_t,std::uint32_t> ScriptSession::rebuildTrackables(std::span<const std::uint8_t> bytes) {
    constexpr size_t budget=16u*1024u*1024u;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || trackablesRebuilt_ || !trackables_.empty() || std::any_of(objects_.begin(),objects_.end(),[](auto& object){return object.kind==NativeKind::Trackable;}) || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Trackable rebuild requires a fresh quiescent session");Binary in(openSnapshot(bytes,budget));in.expect(tag("STKB"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest())throw std::runtime_error("Trackable snapshot map or version differs");auto count=in.count(8,65536);if(count>1048576-objects_.size())throw std::runtime_error("Session native object budget exceeded");std::vector<Object> pending;pending.reserve(count);std::map<std::uint32_t,std::uint32_t> result;std::map<std::uint32_t,std::shared_ptr<ScriptTrackable>> trackables;for(unsigned i=0;i<count;++i){auto saved=in.u32(),live=in.u32(),id=handleBase+std::uint32_t(objects_.size()+pending.size());if(!saved || live>1 || !result.emplace(saved,id).second)throw std::runtime_error("Invalid trackable identity");if(!live){pending.push_back(Object{NativeKind::Trackable,false,std::monostate{}});continue;}if(trackables.size()>=8192)throw std::runtime_error("Trackable budget exceeded");auto state=std::make_shared<ScriptTrackable>();state->model=snapshotText(in,65536);state->x=std::bit_cast<float>(in.u32());state->y=std::bit_cast<float>(in.u32());state->facing=std::bit_cast<float>(in.u32());if(state->model.empty() || !std::isfinite(state->x) || !std::isfinite(state->y) || !std::isfinite(state->facing))throw std::runtime_error("Invalid trackable state");trackables.emplace(id,state);pending.push_back(Object{NativeKind::Trackable,true,std::move(state)});}in.finish();objects_.reserve(objects_.size()+pending.size());for(auto& object:pending)objects_.push_back(std::move(object));trackables_.swap(trackables);trackablesRebuilt_=true;return result;
}
void ScriptSession::bindTrackableNatives() {
    bind("CreateTrackable","trackable",{"string","real","real","real"},[this](auto& vm,auto a){auto path=a[0].text?*a[0].text:std::string{};auto x=std::bit_cast<float>(a[1].bits),y=std::bit_cast<float>(a[2].bits),facing=std::bit_cast<float>(a[3].bits);if(path.empty())return vm.handle("trackable",0);if(!std::isfinite(x) || !std::isfinite(y) || !std::isfinite(facing) || trackables_.size()>=8192)throw std::runtime_error("Invalid trackable or trackable budget exceeded");auto value=std::make_shared<ScriptTrackable>();value->model=std::move(path);value->x=x;value->y=y;value->facing=facing;auto id=create(NativeKind::Trackable);std::get<std::shared_ptr<ScriptTrackable>>(object(id,NativeKind::Trackable).state)=value;trackables_.emplace(id.bits,std::move(value));return id;});
    for(auto [name,hit]:std::initializer_list<std::pair<const char*,bool>>{{"TriggerRegisterTrackableHitEvent",true},{"TriggerRegisterTrackableTrackEvent",false}})bind(name,"event",{"trigger","trackable"},[this,hit](auto&,auto a){object(a[0],NativeKind::Trigger);object(a[1],NativeKind::Trackable);ScriptEvent event;event.owner=a[0].bits;event.target=a[1].bits;event.kind=hit?ScriptEvent::Kind::TrackableHit:ScriptEvent::Kind::TrackableTrack;event.event=hit?7:8;auto id=createTriggerEvent(a[0]);std::get<ScriptEvent>(object(id,NativeKind::Event).state)=std::move(event);return id;});
    bind("GetTriggeringTrackable","trackable",{},[this](auto& vm,auto){return vm.handle("trackable",contexts_.empty()?0:contexts_.back().triggeringTrackable);});
}
void ScriptSession::trackableEvent(std::uint32_t id,bool hit) {
    if(!alive(id,NativeKind::Trackable))return;std::vector<std::uint32_t> matches;auto kind=hit?ScriptEvent::Kind::TrackableHit:ScriptEvent::Kind::TrackableTrack;for(auto event:eventHandles_)if(alive(event,NativeKind::Event)){auto& value=std::get<ScriptEvent>(objects_[event-handleBase].state);if(value.kind==kind && value.target==id)matches.push_back(event);}for(auto event:matches){ScriptContext context;context.triggeringTrackable=id;fire(event,context);}
}
